class SimpleControlIconFactory:
    """Clean, high-contrast minimal icons for power, grid bolt, and tamper lock."""

    @staticmethod
    def _rect(img, x0, y0, x1, y1, color):
        w, h = img.width(), img.height()
        x0, y0 = max(0, int(x0)), max(0, int(y0))
        x1, y1 = min(w, int(x1)), min(h, int(y1))
        if x1 > x0 and y1 > y0:
            img.put(color, to=(x0, y0, x1, y1))

    @staticmethod
    def _ring(img, cx, cy, r_out, r_in, color):
        w, h = img.width(), img.height()
        ro2, ri2 = r_out * r_out, r_in * r_in
        for y in range(max(0, int(cy - r_out - 1)), min(h, int(cy + r_out + 2))):
            for x in range(max(0, int(cx - r_out - 1)), min(w, int(cx + r_out + 2))):
                d2 = (x - cx) ** 2 + (y - cy) ** 2
                if ri2 <= d2 <= ro2:
                    img.put(color, (x, y))

    @classmethod
    def make_bakery_icon(cls):
        img = tk.PhotoImage(width=36, height=36)
        cls._rect(img, 4, 7, 32, 29, BLUE_PRIMARY)
        cls._rect(img, 8, 12, 28, 25, YELLOW_SOFT)
        cls._rect(img, 10, 13, 26, 15, MAGENTA_ACCENT)
        cls._rect(img, 10, 20, 15, 24, YELLOW_ACCENT)
        cls._rect(img, 17, 20, 22, 24, YELLOW_ACCENT)
        return img

    @classmethod
    def make_power_icon(cls):
        img = tk.PhotoImage(width=24, height=24)
        cls._ring(img, 12, 12, 9, 6.5, "#FFFFFF")
        cls._rect(img, 11, 2, 13, 12, "#FFFFFF")
        return img

    @classmethod
    def make_bolt_icon(cls):
        img = tk.PhotoImage(width=24, height=24)
        pts = [
            (13, 2, 16, 2), (12, 4, 15, 4), (11, 6, 14, 6), (10, 8, 14, 8),
            (8, 10, 17, 10), (7, 12, 16, 12), (10, 14, 15, 14),
            (9, 16, 14, 16), (8, 18, 12, 18), (7, 20, 10, 20)
        ]
        for x0, y, x1, _ in pts:
            cls._rect(img, x0, y, x1, y + 2, "#FEF08A")
        return img

    @classmethod
    def make_lock_icon(cls, unlocked=False):
        img = tk.PhotoImage(width=24, height=24)
        shift = 3 if unlocked else 0
        cls._ring(img, 12 + shift, 9, 6, 3.8, "#FFFFFF")
        cls._rect(img, 6, 10, 18, 21, "#FDE047" if not unlocked else "#FCA5A5")
        cls._rect(img, 11, 14, 13, 18, TEXT_DARK)
        return img


